'use strict';
(() => {
 const tiers=[{name:'初心小屋',need:0},{name:'森木書房',need:4},{name:'石爐暖居',need:9},{name:'星圖工房',need:16},{name:'星晶公會小屋',need:24}];
 const ensure=()=>{data.homeMaterials??={wood:0,stone:0,metal:0};data.homeTier??=0}; ensure();
 const tier=()=>Math.max(0,Math.min(4,Math.min(...Object.values(data.homeMaterials).map(n=>Math.floor(Number(n)||0)/tiers[4].need*4))));
 const priorUpgradeSave=upgradeSave; upgradeSave=function(){priorUpgradeSave();ensure();data.homeTier=Math.max(data.homeTier,tier())};
 const oldPanel=missionPanel; missionPanel=function(){return oldPanel().replace('<label class="field" for="mission-mode">',`<fieldset class="reward-policy"><legend>小屋建造材料</legend><p class="subtle">家長決定完成後可獲得嘅材料。約 3–8 個任務可升一級。</p><div class="form-grid"><label class="field">木材<input class="input" name="wood" type="number" min="0" max="10" value="1"></label><label class="field">石材<input class="input" name="stone" type="number" min="0" max="10" value="1"></label><label class="field">金屬<input class="input" name="metal" type="number" min="0" max="10" value="1"></label></div></fieldset><label class="field" for="mission-mode">`)};
 document.addEventListener('submit',e=>{if(e.target.id!=='mission-form'||sessionRole!=='parent')return;const f=new FormData(e.target),title=String(f.get('title')||'').trim(),m={wood:Math.max(0,Number(f.get('wood'))||0),stone:Math.max(0,Number(f.get('stone'))||0),metal:Math.max(0,Number(f.get('metal'))||0)};setTimeout(()=>{const q=data.quests.find(q=>q.title===title&&!q.materials);if(q){q.materials=m;persist()}},0)},true);
 const oldFinish=finishQuest; finishQuest=function(mode){const q=timer&&data.quests.find(q=>q.id===timer.id);oldFinish(mode);if(mode==='complete'&&q?.done&&!q.materialsGranted){ensure();const m=q.materials||{wood:1,stone:1,metal:1};for(const k of Object.keys(data.homeMaterials))data.homeMaterials[k]+=Number(m[k])||0;q.materialsGranted=true;const before=data.homeTier;upgradeSave();persist();if(data.homeTier>before)notify(`小屋升至「${tiers[data.homeTier].name}」！新傢俬與魔法燈光已出現。`);else notify(`建造材料：木材 ${m.wood}、石材 ${m.stone}、金屬 ${m.metal}`)}};
 const originalScene=updateRoomScene; updateRoomScene=function(){ensure();const scene=desiredRoomScene(),info=ROOM_SCENES[scene],old=info.image;info.image=`assets/home-tier-${data.homeTier+1}.png`;const r=originalScene();info.image=old;return r};
 const baseRoom=room; room=function(){ensure();const next=tiers[Math.min(4,data.homeTier+1)];return baseRoom().replace('<section class="room-clock-panel"',`<div class="home-upgrade-status">${icon('home')} <strong>${tiers[data.homeTier].name}</strong><span>木 ${data.homeMaterials.wood} · 石 ${data.homeMaterials.stone} · 鐵 ${data.homeMaterials.metal}</span><small>下一階：每種材料 ${next.need}</small></div><section class="room-clock-panel"`) };
 render();
})();
